package doctor

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// TestCheckDelegatedWorkerArchetypes pins ethos-e05k: a repo-local
// "implement" or "test" archetype missing require_delegated_worker must
// FAIL and name the repo-local layer, so an operator knows a re-run of
// `ethos seed` alone will not fix it (a repo-local file shadows the
// global one regardless of the global file's own state).
func TestCheckDelegatedWorkerArchetypes(t *testing.T) {
	writeArchetype := func(t *testing.T, dir, name, body string) {
		t.Helper()
		require.NoError(t, os.MkdirAll(dir, 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(dir, name+".yaml"), []byte(body), 0o644))
	}

	t.Run("not in a repo", func(t *testing.T) {
		r := CheckDelegatedWorkerArchetypes("")
		assert.True(t, r.Passed())
		assert.Equal(t, "not in a repo", r.Detail)
	})

	t.Run("no archetypes deployed anywhere — not this check's concern", func(t *testing.T) {
		storeRoot := t.TempDir()
		r := CheckDelegatedWorkerArchetypes(storeRoot)
		assert.Equal(t, "PASS", r.Status, "detail: %s", r.Detail)
	})

	t.Run("repo-local archetype with the guard set → PASS", func(t *testing.T) {
		storeRoot := t.TempDir()
		archDir := filepath.Join(storeRoot, ".punt-labs", "ethos", "archetypes")
		writeArchetype(t, archDir, "implement", "name: implement\nrequire_delegated_worker: true\n")
		writeArchetype(t, archDir, "test", "name: test\nrequire_delegated_worker: true\n")
		r := CheckDelegatedWorkerArchetypes(storeRoot)
		assert.Equal(t, "PASS", r.Status, "detail: %s", r.Detail)
	})

	t.Run("repo-local archetype missing the field → FAIL, names repo-local", func(t *testing.T) {
		// This is the exact silent-zero-enforcement shape ethos-e05k names:
		// pre-field YAML on disk, the field simply absent, parsing as false.
		storeRoot := t.TempDir()
		archDir := filepath.Join(storeRoot, ".punt-labs", "ethos", "archetypes")
		writeArchetype(t, archDir, "implement", "name: implement\n")
		writeArchetype(t, archDir, "test", "name: test\nrequire_delegated_worker: true\n")
		r := CheckDelegatedWorkerArchetypes(storeRoot)
		assert.Equal(t, "FAIL", r.Status)
		assert.Contains(t, r.Detail, "implement (repo-local)")
		assert.NotContains(t, r.Detail, "test (repo-local)")
		assert.Contains(t, r.Detail, "ethos seed")
	})

	t.Run("only global has the archetype and it is stale → FAIL, names global", func(t *testing.T) {
		storeRoot := t.TempDir()
		r := checkDelegatedWorkerArchetypesWithGlobal(t, storeRoot, t.TempDir(),
			map[string]string{"implement": "name: implement\n", "test": "name: test\nrequire_delegated_worker: true\n"})
		assert.Equal(t, "FAIL", r.Status)
		assert.Contains(t, r.Detail, "implement (global)")
	})

	t.Run("repo-local shadows a fine global with a stale copy → FAIL still names repo-local", func(t *testing.T) {
		// This is the "shadow" scenario the bead calls out by name: `ethos
		// seed` refreshing the global layer does nothing here, because the
		// repo-local file resolves first.
		storeRoot := t.TempDir()
		globalRoot := t.TempDir()
		writeArchetype(t, filepath.Join(globalRoot, "archetypes"), "implement", "name: implement\nrequire_delegated_worker: true\n")
		r := checkDelegatedWorkerArchetypesWithGlobal(t, storeRoot, globalRoot,
			map[string]string{"implement": "name: implement\n"})
		assert.Equal(t, "FAIL", r.Status)
		assert.Contains(t, r.Detail, "implement (repo-local)",
			"the repo-local file resolves ahead of a fine global one and must be named, not the global layer")
	})
}

// checkDelegatedWorkerArchetypesWithGlobal writes repoLocal archetype files
// under storeRoot and exercises CheckDelegatedWorkerArchetypes's global
// fallback by pointing HOME at globalRoot — the same os.UserHomeDir() path
// the production code resolves.
func checkDelegatedWorkerArchetypesWithGlobal(t *testing.T, storeRoot, globalRoot string, repoLocal map[string]string) Result {
	t.Helper()
	t.Setenv("HOME", globalRoot)
	archDir := filepath.Join(storeRoot, ".punt-labs", "ethos", "archetypes")
	for name, body := range repoLocal {
		require.NoError(t, os.MkdirAll(archDir, 0o755))
		require.NoError(t, os.WriteFile(filepath.Join(archDir, name+".yaml"), []byte(body), 0o644))
	}
	globalArchDir := filepath.Join(globalRoot, ".punt-labs", "ethos", "archetypes")
	if _, err := os.Stat(globalArchDir); err != nil {
		// nothing pre-seeded by the caller — leave absent
	}
	return CheckDelegatedWorkerArchetypes(storeRoot)
}

